theorems.type:
∀ {H : Type u_1} {inst : NormedAddCommGroup H} {inst_1 : InnerProductSpace Real H} {inst_2 : CompleteSpace H}
  {X : Type u_2} {inst_3 : RKHS Real H X Real} [self : BoundedKernel H] (x : X),
  Real.instLE.le (inst.norm (ContinuousLinearMap.funLike.coe (RKHS.kerFun H x) 1)) (self.bound H X)

∀ {Ω : Type u_1} {inst : MeasurableSpace Ω} {f : Ω → Real} {μ : MeasureTheory.Measure Ω} {a b : Real}
  [self : ProbabilityTheory.BoundedRandomVariable f μ a b],
  Filter.Eventually (fun ω => Set.instMembership.mem (Set.Icc a b) (f ω)) (MeasureTheory.ae μ)

∀ {X : Type u_1} {inst : MeasurableSpace X} {m : Nat} {μ : MeasureTheory.Measure X}
  {hμ : MeasureTheory.IsProbabilityMeasure μ} {m_1 : Nat} {μ_1 : MeasureTheory.Measure X}
  {hμ_1 : MeasureTheory.IsProbabilityMeasure μ_1},
  Eq { m := m, μ := μ, hμ := hμ } { m := m_1, μ := μ_1, hμ := hμ_1 } → And (Eq m m_1) (Eq μ μ_1)

∀ {α : Type u_1} {inst : Fintype α} {prob : α → Real} {prob_nonneg : ∀ (a : α), Real.instLE.le 0 (prob a)}
  {prob_sum_one : Eq (Finset.univ.sum fun a => prob a) 1} {prob_1 : α → Real}
  {prob_nonneg_1 : ∀ (a : α), Real.instLE.le 0 (prob_1 a)} {prob_sum_one_1 : Eq (Finset.univ.sum fun a => prob_1 a) 1},
  Eq { prob := prob, prob_nonneg := prob_nonneg, prob_sum_one := prob_sum_one }
      { prob := prob_1, prob_nonneg := prob_nonneg_1, prob_sum_one := prob_sum_one_1 } →
    Eq prob prob_1

∀ {m : Nat} {assign : Fin (instHMul.hMul 2 m) → Bool}
  {card_true : Eq (Finset.filter (fun i => Eq (assign i) Bool.true) Finset.univ).card m}
  {assign_1 : Fin (instHMul.hMul 2 m) → Bool}
  {card_true_1 : Eq (Finset.filter (fun i => Eq (assign_1 i) Bool.true) Finset.univ).card m},
  Eq { assign := assign, card_true := card_true } { assign := assign_1, card_true := card_true_1 } → Eq assign assign_1

∀ {X : Type u_1} [inst : MeasurableSpace X] {Y : Type u_2} [inst_1 : MeasurableSpace Y] {H : Type u_3}
  [inst_2 : NormedAddCommGroup H] [inst_3 : InnerProductSpace Real H] [inst_4 : CompleteSpace H]
  [inst_5 : RKHS Real H (Prod X Y) Real] (P : MeasureTheory.Measure (Prod X Y)), Real.instLE.le 0 (hsicDef P)
